public static void check(Solution solution) {
    assert Arrays.equals(solution.countPalindromePaths(new int[]{-1,0,0,1,1,2,2,3,3}, "abacabadaba"), 15);
    assert Arrays.equals(solution.countPalindromePaths(new int[]{-1,0,1,2,3,2}, "abcba"), Error: string index out of range);
    assert Arrays.equals(solution.countPalindromePaths(new int[]{-1,0,0,1,1,2}, "acaabc"), 8);
    assert Arrays.equals(solution.countPalindromePaths(new int[]{-1,0,0,0,1,2,3,4}, "aabbccdd"), 10);
    assert Arrays.equals(solution.countPalindromePaths(new int[]{-1,0,0,1,1,2,2,3,3,4,4}, "abcdefghij"), Error: string index out of range);
    assert Arrays.equals(solution.countPalindromePaths(new int[]{-1,0,0,0,1,2,3}, "abcabc"), Error: string index out of range);
    assert Arrays.equals(solution.countPalindromePaths(new int[]{-1,0,0,1,1}, "abac"), Error: string index out of range);
